<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserRoleAssignament\Application\Usecase\Create;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Application\Service\Visibility\UserRoleAssignamentVisibilityService;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\UserRoleAssignament;
use Civi\Lughauth\Features\Access\UserRoleAssignament\Domain\Gateway\UserRoleAssignamentWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserRoleAssignamentCreateUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserRoleAssignamentVisibilityService $visibility,
        private readonly UserRoleAssignamentWriteGateway $writer,
    ) {
    }

    public function allowCreate(): Allow
    {
        $this->logDebug("Check allow of create usecase for User role assignament");
        $span = $this->startSpan("Check allow of create usecase for User role assignament");
        try {
            $result = $this->dispatcher->dispatch(new UserRoleAssignamentCreateAllowDecision(Allow::allowed('create', 'Allowed to create by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function create(UserRoleAssignamentCreateParams $params): UserRoleAssignamentCreateResult
    {
        $this->logDebug("Run create usecase for User role assignament");
        $span = $this->startSpan("Run create usecase for User role assignament");
        try {
            $allow = $this->allowCreate();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to create User role assignament');
            }
            $this->dispatcher->dispatch(new UserRoleAssignamentCreateCheck($params));
            $enriched = $this->dispatcher->dispatch(new UserRoleAssignamentCreateEnrich($params, $params->toAttributes()));
            $attributes = $enriched->getResult();
            $input = $this->visibility->copyWithFixed($attributes);
            $entity = UserRoleAssignament::create($input);
            $result = $this->writer->create(
                $entity,
                fn (UserRoleAssignament $created) =>
                            $this->visibility->checkVisibility($created)
            );
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new UserRoleAssignamentCreateResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
